import {SUKUNA_META as META} from './sukuna-meta.js';
import {SUKUNA_SKILLS,sukunaPose} from '../characters/sukuna.js';
import {cinematicSteps} from '../engine/ultimate-rules.js';
const TAU=Math.PI*2;
const clamp=v=>Math.max(0,Math.min(1,v));
// Presentation only: every pulse follows the existing combat clock; no new RNG or damage.
function halo(ctx,x,y,r,color,alpha=.5){ctx.save();ctx.globalCompositeOperation='lighter';ctx.globalAlpha*=alpha;const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,color);g.addColorStop(.28,color+'aa');g.addColorStop(1,color+'00');ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,r,0,TAU);ctx.fill();ctx.restore();}
function ring(ctx,x,y,r,alpha,color='#ff3458'){ctx.save();ctx.globalAlpha*=alpha;ctx.strokeStyle=color;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(x,y,r,r*.38,0,0,TAU);ctx.stroke();ctx.restore();}
function slashLines(ctx,x,y,reach,phase,alpha,reduced=false){ctx.save();ctx.translate(x,y);ctx.globalAlpha*=alpha;ctx.lineCap='round';const count=reduced?2:7;for(let i=0;i<count;i++){const angle=-.9+i*2.399,offset=Math.sin(i*3.7+phase)*reach*.45;ctx.save();ctx.rotate(angle);ctx.strokeStyle='#190815';ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(-reach,offset);ctx.lineTo(reach,offset-24);ctx.stroke();ctx.strokeStyle='#ff294d';ctx.lineWidth=4;ctx.stroke();ctx.strokeStyle='#fff2dc';ctx.lineWidth=1.3;ctx.stroke();ctx.restore();}ctx.restore();}
export function sukunaSprite(ctx,images,key,row,col,x,y,scale=1,angle=0,face=1){const im=images[key],m=META[key];if(!im?.complete||!im.naturalWidth||!m)return;col=Math.max(0,Math.min(m.columns-1,col));row=Math.max(0,Math.min(m.rows-1,row));const [w,h]=m.frameSize,[px,py]=m.pivots[row*m.columns+col];ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale(scale*m.drawScale*(face<0?-1:1),scale*m.drawScale);ctx.drawImage(im,col*w,row*h,w,h,-px,-py,w,h);ctx.restore();}
export function drawSukunaActor(ctx,images,d,f,hurt=false,override=null){let key='sukuna',p=override||sukunaPose(f,hurt);const c=d.personalUltimate?.cinematic,a=d.personalUltimate?.attack,tc=d.teamUltimate?.cinematic;
 if(f.introAge!=null){const n=Math.min(11,Math.floor(f.introAge/2.5*12));if(n<3)return;key='sukuna_intro';p={row:Math.floor(n/6),frame:n%6};}
 else if((c?.kind==='shrine'&&c.ownerUid===f.uid)||tc?.leaderUid===f.uid){const charge=c?.kind==='shrine'?c:tc,progress=charge.elapsed/cinematicSteps(charge);key='sukuna_ultimate_actor';p={row:0,frame:progress<.12?0:progress<.85?1:2};}
 else if(a?.kind==='shrine'&&a.ownerUid===f.uid&&(a.phase==='warning'||d.tick-a.launch<30)){key='sukuna_ultimate_actor';p={row:0,frame:a.phase==='warning'?2:3};}
 else if(SUKUNA_SKILLS[f.state]&&!hurt){key='sukuna_cast';p={row:{dismantle:0,cleave:1,furnace:2}[f.state],frame:Math.min(5,Math.floor(f.age/SUKUNA_SKILLS[f.state].duration*6))};}
 if(f.state==='defeat'){key='sukuna';p={row:7,frame:Math.min(5,Math.floor((d.tick-(f.deathTick??d.tick))/6))};}sukunaSprite(ctx,images,key,p.row,p.frame,f.x,f.y,.98,0,f.face);}
export function drawSukunaBack(ctx,images,d,clock=0,reduced=false){for(const f of d.fighters)if(f.id==='sukuna'&&f.hp>0){if(f.introAge!=null){const age=f.introAge;if(age<.625)sukunaSprite(ctx,images,'sukuna_intro',0,Math.min(2,Math.floor(age/.625*3)),f.x,f.y,.98);else if(age>1.25&&age<2){ctx.save();ctx.globalAlpha=(2-age)/.75;sukunaSprite(ctx,images,'sukuna_intro_vfx',0,5,f.x,f.y-28,.65);ctx.restore();}if(age>.55){ring(ctx,f.x,f.y,30+age*25,clamp(2.5-age)*.55);if(!reduced){ctx.save();ctx.globalAlpha=.4*clamp(2.5-age);sukunaSprite(ctx,images,'sukuna_intro_vfx',1,Math.min(5,Math.floor(age/2.5*6)),f.x,f.y-45,.75);ctx.restore();}}}
 else{const c=d.personalUltimate?.cinematic,tc=d.teamUltimate?.cinematic,charging=(c?.kind==='shrine'&&c.ownerUid===f.uid)||tc?.leaderUid===f.uid;if(charging){const charge=c?.kind==='shrine'?c:tc,p=charge.elapsed/cinematicSteps(charge);halo(ctx,f.x,f.y-42,75+p*55,'#ff244e',.28);ring(ctx,f.x,f.y,35+p*60,.7);if(!reduced)for(let i=0;i<2;i++){const q=(p*2+i*.5)%1;ring(ctx,f.x,f.y,30+q*90,(1-q)*.65);}}
 if(SUKUNA_SKILLS[f.state]&&!f.hit){const p=clamp(f.age/SUKUNA_SKILLS[f.state].cast),fire=f.state==='furnace';halo(ctx,f.x+f.face*36,f.y-60,25+p*(fire?65:32),fire?'#ff9b28':'#ff244e',.25+p*.35);if(fire){ctx.save();ctx.globalAlpha=.35+p*.5;sukunaSprite(ctx,images,'sukuna_vfx',2,Math.min(1,Math.floor(p*2)),f.x+f.face*45,f.y-63,.25+p*.3,0,f.face);ctx.restore();}else if(p>.55){ctx.save();ctx.globalAlpha=(p-.55)*1.4;sukunaSprite(ctx,images,'sukuna_vfx',f.state==='cleave'?1:0,1,f.x+f.face*40,f.y-55,.38+p*.15,0,f.face);ctx.restore();}}}}
 const a=d.personalUltimate?.attack;if(a?.kind!=='shrine')return;
 if(a.phase==='warning'){const p=clamp((d.tick-a.born)/36);ctx.save();ctx.globalAlpha=.25+p*.45;sukunaSprite(ctx,images,'sukuna_ultimate_vfx',1,Math.min(1,Math.floor(p*2)),a.x,a.y,1.15);sukunaSprite(ctx,images,'sukuna_ultimate_vfx',0,Math.min(1,Math.floor(p*2)),a.x,a.y-100,.85+p*.15);ctx.restore();ctx.save();ctx.strokeStyle='#ff4565';ctx.lineWidth=3;ctx.setLineDash([9,7]);ctx.beginPath();ctx.ellipse(a.x,a.y,200,145,0,0,TAU);ctx.stroke();ctx.restore();}
 else{const age=d.tick-a.launch,pulse=(age%30)/30,fade=clamp((180-age)/24);ctx.save();ctx.globalAlpha=fade;sukunaSprite(ctx,images,'sukuna_ultimate_vfx',1,pulse<.24?3:2,a.x,a.y,1.15);halo(ctx,a.x,a.y-65,175,'#ff244e',reduced?.12:.22*(1-pulse));ctx.save();ctx.globalAlpha=.95;sukunaSprite(ctx,images,'sukuna_ultimate_vfx',0,age<12?1:age<24?2:3,a.x,a.y-115,1.02);ctx.restore();ring(ctx,a.x,a.y,190,.5);ctx.restore();}}
export function drawSukunaWorld(ctx,images,d,clock=0,reduced=false){for(const f of d.fighters)if(f.id==='sukuna'&&f.hp>0&&f.introAge==null&&d.tick<f.reverseUntil)sukunaSprite(ctx,images,'sukuna_vfx',3,Math.floor(clock*8)%6,f.x,f.y-55,.6);
 for(const f of d.fighters)if(f.id==='sukuna'&&f.hp>0&&f.introAge==null&&SUKUNA_SKILLS[f.state]){const spec=SUKUNA_SKILLS[f.state],release=f.age-spec.cast;if(release>=0&&release<.23){const p=release/.23,fire=f.state==='furnace';ctx.save();ctx.globalAlpha=(1-p)*.8;sukunaSprite(ctx,images,'sukuna_vfx',fire?2:f.state==='cleave'?1:0,fire?0:3,f.x+f.actionX*65,f.y-55+f.actionY*30,fire?.7:1.1,fire?Math.atan2(f.actionY,f.actionX):f.face<0?Math.PI:0);ctx.restore();if(!reduced)ring(ctx,f.x,f.y,30+p*90,(1-p)*.5);}}
 const a=d.personalUltimate?.attack;if(a?.kind==='shrine'&&a.phase==='travel'){const age=d.tick-a.launch,pulse=(age%30)/30,fade=clamp((180-age)/24);ctx.save();ctx.globalAlpha=fade;if(pulse<.52){const p=pulse/.52;ctx.save();ctx.globalAlpha=(1-p)*(reduced?.25:.85);sukunaSprite(ctx,images,'sukuna_ultimate_vfx',2,p<.45?0:1,a.x,a.y-25,1.05+p*.15);ctx.restore();if(!reduced)slashLines(ctx,a.x,a.y-30,155,Math.floor(age/30),Math.pow(1-p,2)*.65);}ctx.restore();}}
export function drawSukunaShot(ctx,images,s,x,y,clock,reduced=false){const fire=s.kind==='furnace',angle=Math.atan2(s.vy,s.vx);ctx.save();if(!fire&&!reduced){for(let i=2;i>0;i--){ctx.globalAlpha=.16/i;sukunaSprite(ctx,images,'sukuna_vfx',0,2,x-Math.cos(angle)*i*27,y-Math.sin(angle)*i*27,.85-i*.07,angle);}}ctx.globalAlpha=1;halo(ctx,x,y,fire?85:35,fire?'#ff9b28':'#ff244e',reduced?.15:.4);sukunaSprite(ctx,images,'sukuna_vfx',fire?2:0,fire?2:2+Math.floor(clock*12)%2,x,y,fire?1.5:.85,angle);ctx.restore();}
export function drawSukunaBurst(ctx,images,b,reduced=false){const p=clamp(1-b.life/b.max),fire=b.action==='furnace',slash=b.action==='cleave'||!b.action,row=fire?2:slash?1:0;ctx.save();ctx.globalAlpha=Math.pow(1-p,.7);halo(ctx,b.x,b.y,fire?100:65,fire?'#ffb63e':'#ff3458',p<.2?.85:.35);sukunaSprite(ctx,images,'sukuna_vfx',row,fire?(p<.55?4:5):p<.22?3:p<.6?4:5,b.x,b.y,(fire?1.3:b.action?1.05:.52)*(1+p*.18),b.angle||0);if(p<.18&&!reduced)slashLines(ctx,b.x,b.y,fire?80:58,p*5,(1-p/.18)*.55,true);ring(ctx,b.x,b.y+24,(fire?30:15)+p*(fire?120:65),(1-p)*.6,fire?'#ffb63e':'#ff3458');ctx.restore();}
export function drawSukunaChat(ctx,images,c,line='Domain Expansion: Malevolent Shrine.'){const m=META.sukuna_dialogue,[fw,fh]=m.frameSize,col=1,idx=1,b=m.bounds[idx],pivot=m.pivots[idx],p=c.elapsed/cinematicSteps(c),scale=Math.min(900/(b[2]-b[0]),230/(b[3]-b[1]));ctx.save();ctx.globalAlpha=Math.max(0,Math.min(1,p*10,(1-p)*12));
 // The complete native frame is fitted into the lower screen, including soft border pixels.
 const x=480-(b[0]+b[2]-2*pivot[0])*scale/2,y=515-(b[3]-pivot[1])*scale;sukunaSprite(ctx,images,'sukuna_dialogue',0,col,x,y,scale);
 ctx.textAlign='left';ctx.fillStyle='#fff1e5';ctx.font='bold 22px Georgia';ctx.fillText('RYOMEN SUKUNA',414,420,420);ctx.font='bold 20px Georgia';const lines=line==='Domain Expansion: Malevolent Shrine.'?['Domain Expansion:','Malevolent Shrine.']:[line];for(const [i,t] of lines.entries())ctx.fillText(t,414,455+i*27,420);ctx.restore();}
export function drawSukunaCinematic(ctx,images,d){const c=d.personalUltimate?.cinematic;if(c?.kind==='shrine')drawSukunaChat(ctx,images,c);}
